"""SFSC precision-v2 test inference: exact pinned source snapshot."""
import base64, hashlib, io, json, os, sys, time, zipfile
from pathlib import Path

print(json.dumps({"event": "input_mounts", "paths": sorted(os.listdir("/kaggle/input"))}), flush=True)

payload = ''
hashes = {'approach/geometry.py': '19e4bf477bf2fa74562b148e5e0078bce23fc88ab6577c603dc7eebe2435e1d9', 'approach/pipeline.py': 'f2a9b76f6082a15da1f5b52ed46155f32d428ac9fe4899464d6e080494a252e2', 'src/sfsc/dataset.py': '5a9997a2cd5f64ec90b241e276d1cc4545ee8e8ca75a940767b2fbddf590606a', 'src/sfsc/evaluation.py': 'd61479fcc7ba5182c5a14636584dab6572ff6c3c693cfabd982a38c338e1c7b7', 'src/sfsc/contracts.py': 'b61eedb6a973017e10c805b2bb6515c81eace26c2d456b417e862a5dd66a9a02'}

arcroot = Path("/kaggle/working/sfsc-source")
arcroot.mkdir(exist_ok=False)
with zipfile.ZipFile(io.BytesIO(base64.b64decode(payload))) as archive:
    for name, expected in hashes.items():
        data = archive.read(name)
        assert hashlib.sha256(data).hexdigest() == expected, name
        target = arcroot / name
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)

import numpy as np
import tensorflow as tf

sys.path.insert(0, str(arcroot / "src"))
sys.path.insert(0, str(arcroot / "approach"))
from sfsc.dataset import submission

import pipeline

data_root = Path(
    "/kaggle/input/competitions/filament-segmentation-2026/MAGFiLO_1.0_Kaggle_2026"
)
checkpoint_candidates = sorted(Path("/kaggle/input").rglob("recipe.json"))
assert checkpoint_candidates, "Checkpoint dataset not mounted"
checkpoint = checkpoint_candidates[0].parent
output = Path(".")

recipe = json.loads((checkpoint / "recipe.json").read_text())
calibration = json.loads((checkpoint / "calibration.json").read_text())
config = recipe["config"]
selected = calibration["selected"]
assert selected == recipe["postprocess"], "Postprocess mismatch between recipe and calibration"
best = json.loads((checkpoint / "best.json").read_text())
assert best["epoch"] == recipe["best_epoch"], "best.json epoch mismatch"

model = pipeline.build_model(config["base_filters"])
model.load_weights(checkpoint / "best.weights.h5")
print(json.dumps(
    {
        "event": "model_loaded",
        "epoch": best["epoch"],
        "checkpoint_validation_pq": best["pq"],
        "postprocess": selected,
        "parameters": model.count_params(),
    },
    allow_nan=False,
), flush=True)

test_images = sorted((data_root / "test/test_images").glob("*.jpeg"))
assert test_images, "Competition test images missing"

started = time.monotonic()
predictions = output / "predictions"
predictions.mkdir(exist_ok=True)
instances_per_image = {}
for index, path in enumerate(test_images, 1):
    image = pipeline.read_image(str(path))
    probability = pipeline.infer(model, image, config)
    labels = pipeline.instances(probability, selected)
    np.save(predictions / f"{path.stem}.npy", labels.astype(np.int32), allow_pickle=False)
    instances_per_image[path.name] = int(labels.max(initial=0))
    if index == 1 or index % 10 == 0:
        print(json.dumps(
            {
                "event": "test_prediction",
                "index": index,
                "images": len(test_images),
                "elapsed_seconds": round(time.monotonic() - started, 3),
            },
            allow_nan=False,
        ), flush=True)

inference_seconds = time.monotonic() - started
report = submission(data_root, predictions, output / "submission.csv")
report.update(
    status="completed",
    phase="submit",
    upstream_epoch=best["epoch"],
    upstream_checkpoint_validation_pq=best["pq"],
    selected_postprocess=selected,
    nonempty_images=sum(value > 0 for value in instances_per_image.values()),
    inference_seconds=round(inference_seconds, 3),
)
(output / "submit-report.json").write_text(json.dumps(report, indent=2))
print(json.dumps(report, indent=2, allow_nan=False))
